payload.input:
const results = await Promise.allSettled([
tools.mcp__git_bash__run({command:"git status --short && cat AGENTS.md docs/결정사항.md docs/시나리오.md docs/contract.md docs/assets.csv",description:"Read overview rules scenario and asset contracts",workdir:"C:/dev/S-SHE"}),
tools.mcp__git_bash__run({command:"cat index.html && find src -maxdepth 3 -type f",description:"Read current page and source folder inventory",workdir:"C:/dev/S-SHE"})
]); results.forEach(text);

