:root {
  color-scheme: dark;
  font-family: "Pretendard", "Noto Sans KR", "Malgun Gothic", system-ui, sans-serif;
  color: #f4f4ee;
  background: #171b1f;
  font-synthesis: none;
  --accent: #ffc857;
  --muted: #acb3b7;
}

* { box-sizing: border-box; }
body { margin: 0; min-width: 320px; }
button, a { -webkit-tap-highlight-color: transparent; }
button { font: inherit; }
button, a { touch-action: manipulation; }
button:focus-visible, a:focus-visible { outline: 3px solid var(--accent); outline-offset: 5px; }
button { cursor: pointer; }

.overview { max-width: 1760px; margin: auto; padding: 0 40px 28px; }
.overview-header { height: 88px; display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid #343b40; }
.brand { display: inline-flex; align-items: center; gap: 11px; color: inherit; text-decoration: none; font-size: 17px; font-weight: 800; letter-spacing: .13em; }
.brand-symbol { display: grid; place-items: center; width: 30px; height: 34px; border: 1px solid var(--accent); color: var(--accent); font-size: 21px; letter-spacing: 0; }
.scenario-name { font-size: 14px; color: #d1d5d6; }
.scene-heading { display: flex; justify-content: space-between; align-items: end; gap: 24px; padding: 28px 0 21px; }
.eyebrow { margin: 0 0 8px; color: var(--accent); font-size: 12px; font-weight: 700; letter-spacing: .06em; }
h1 { margin: 0; font-size: clamp(24px, 3vw, 36px); letter-spacing: -.05em; line-height: 1.15; }
.scene-instruction { margin: 0 0 3px; color: var(--muted); font-size: 14px; }
.factory-frame { position: relative; width: 100%; background: #252d30; border: 1px solid #454b4c; }
.factory-image { display: block; width: 100%; height: auto; }
.conveyor-zone { position: absolute; left: var(--zone-u); top: var(--zone-v); transform: translate(-50%, -50%); padding: 8px; background: transparent; border: 0; display: flex; align-items: center; flex-direction: column; gap: 10px; color: #fff; }
.zone-marker { display: grid; place-items: center; width: 42px; height: 42px; border: 1px solid var(--accent); border-radius: 50%; background: #171b1f9c; box-shadow: 0 0 0 7px #ffc85725; }
.zone-marker > span { width: 10px; height: 10px; background: var(--accent); border-radius: 50%; }
.zone-label { display: block; text-align: left; padding: 11px 15px; background: #171b1ff2; border: 1px solid #ffc857b3; border-radius: 3px; box-shadow: 0 5px 20px #0003; white-space: nowrap; }
.zone-label strong { display: block; color: var(--accent); font-size: 15px; }
.zone-label strong > span { color: #f4f4ee; margin-left: 8px; font-weight: 600; }
.zone-action { display: flex; justify-content: space-between; gap: 30px; margin-top: 6px; color: #c3c9ca; font-size: 12px; }
.conveyor-zone:hover .zone-label { border-color: var(--accent); background: #242b2f; }
.conveyor-zone:hover .zone-marker { background: #ffc85745; }
.scene-footer { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 17px 0 0; color: var(--muted); font-size: 12px; }
.scene-footer > span { display: inline-flex; align-items: center; gap: 7px; }
.legend-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--accent); }
kbd { padding: 2px 5px; border: 1px solid #495156; border-radius: 3px; font: inherit; font-size: 11px; color: #d4d9da; }

.briefing { width: min(550px, calc(100% - 32px)); max-height: calc(100dvh - 48px); margin: auto; padding: 0; border: 1px solid #596166; border-radius: 5px; color: #f4f4ee; background: #20272b; box-shadow: 0 30px 100px #0008; }
.briefing::backdrop { background: #090e13ba; backdrop-filter: blur(4px); }
.briefing-content { padding: 32px; }
.briefing h2 { margin: 0; font-size: 29px; letter-spacing: -.04em; }
.briefing-role { margin: 8px 0 23px; color: var(--accent); font-size: 14px; }
#briefing-description { margin: 0; color: #d3d8d9; font-size: 15px; line-height: 1.85; }
.briefing-steps { margin: 23px 0; padding: 17px 18px 17px 39px; border: 1px solid #424b50; background: #171d21; color: #d8dcdd; font-size: 13px; line-height: 2.2; }
.briefing-steps li::marker { color: var(--accent); }
.briefing-note { margin: 0 0 23px; font-size: 12px; line-height: 1.7; color: var(--muted); }
.return-button { display: flex; align-items: center; justify-content: space-between; gap: 30px; width: 100%; padding: 14px 17px; border: 0; border-radius: 3px; background: var(--accent); color: #171b1f; font-weight: 700; font-size: 14px; }
.return-button:hover { background: #ffd77f; }
noscript { display: block; margin: 32px; }

@media (max-width: 700px) {
  .overview { padding: 0 18px 22px; }
  .overview-header { height: 70px; }
  .brand { font-size: 14px; gap: 8px; }
  .brand-symbol { width: 26px; height: 29px; font-size: 18px; }
  .scenario-name { font-size: 12px; }
  .scene-heading { display: block; padding: 24px 0 18px; }
  .scene-instruction { margin: 13px 0 0; font-size: 12px; }
  .conveyor-zone { gap: 5px; padding: 4px; }
  .zone-marker { width: 28px; height: 28px; box-shadow: 0 0 0 4px #ffc85725; }
  .zone-marker > span { width: 7px; height: 7px; }
  .zone-label { padding: 7px 9px; }
  .zone-label strong { font-size: 11px; }
  .zone-label strong > span { margin-left: 4px; }
  .zone-action { margin-top: 4px; font-size: 10px; }
  .scene-footer { flex-wrap: wrap; gap: 10px; font-size: 11px; }
  .scene-footer .keyboard-hint { display: none; }
  .briefing-content { padding: 25px; }
  .briefing h2 { font-size: 26px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto; }
}

